// Inicializa o cronômetro real de cada atendimento ativo a partir do pctElapsed inicial
atendimentosAtivos.forEach(a=>{
  if(a.status==='ativo'){
    a.elapsedMs = (a.pctElapsed/100) * a.minutos * 60000;
    a.lastResumeAt = Date.now();
    a.paused = false;
    a.alertPlayed = (a.pctElapsed>=100); // não soa alerta para itens que já nasceram finalizados
  }
});
function getPct(a){
  if(a.status!=='ativo') return a.pctElapsed || 100;
  let elapsed = a.elapsedMs || 0;
  if(!a.paused){ elapsed += (Date.now() - (a.lastResumeAt || Date.now())); }
  const totalMs = Math.max(1, a.minutos*60000);
  return Math.min(100, (elapsed/totalMs)*100);
}
function getRemainingMin(a){
  const pct = getPct(a);
  return Math.max(0, Math.round(a.minutos - (a.minutos*pct/100)));
}

/* ---------------- ALERTA SONORO (RF11 / RNF09) ---------------- */
let audioCtx = null;
function playTimeUpAlert(){
  try{
    if(!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if(audioCtx.state === 'suspended') audioCtx.resume();
    const now = audioCtx.currentTime;
    [0, 0.22].forEach(offset=>{
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.type = 'sine';
      osc.frequency.value = 880;
      gain.gain.setValueAtTime(0.0001, now+offset);
      gain.gain.exponentialRampToValueAtTime(0.35, now+offset+0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, now+offset+0.18);
      osc.connect(gain); gain.connect(audioCtx.destination);
      osc.start(now+offset);
      osc.stop(now+offset+0.2);
    });
  } catch(e){ /* áudio indisponível neste navegador/contexto */ }
}
function checkTimeUpAlerts(){
  atendimentosAtivos.forEach(a=>{
    if(a.status==='ativo' && !a.isPacote && !a.paused){
      if(getRemainingMin(a)<=0){
        if(!a.alertPlayed){ a.alertPlayed = true; playTimeUpAlert(); }
      } else {
        a.alertPlayed = false;
      }
    }
  });
}

