/* ---------------- DINHEIRO E MEIOS DE PAGAMENTO ---------------- */
/* A modelagem define 4 meios: PIX, CREDITO, DEBITO, DINHEIRO */
const PAY_LABELS = {PIX:'Pix', DINHEIRO:'Dinheiro', CREDITO:'Cartão de Crédito', DEBITO:'Cartão de Débito'};
function parseMoney(v){
  if(typeof v === 'number') return v;
  return parseFloat(String(v||'').replace(/\./g,'').replace(',','.')) || 0;
}
function fmtMoney(n){ return 'R$ '+(n||0).toFixed(2).replace('.',','); }
/* "Pix", "Pix + Dinheiro", "-" — usado no histórico e nos cards */
function pagamentosLabel(list){
  if(!list || !list.length) return '-';
  return [...new Set(list.map(pg=>PAY_LABELS[pg.metodo] || pg.metodo))].join(' + ');
}
function somaPagamentos(list){ return (list||[]).reduce((acc,pg)=>acc+(pg.valor||0), 0); }
function locValorTotal(l){ return parseMoney(l.valor); }
function locValorPago(l){ return somaPagamentos(l.pagamentos); }

function getToy(name){ return toys.find(t=>t.name===name); }
function getPacote(name){ return pacotes.find(p=>p.name===name); }
function toyImgTag(name, cls){ const t=getToy(name); return t && t.img ? '<img class="'+cls+'" src="'+t.img+'">' : '<div class="at-thumb-fallback"><i class="fa-solid fa-shapes"></i></div>'; }
function atendimentoThumbTag(a, cls){
  if(a.isPacote){
    const p = getPacote(a.toy);
    return (p && p.img) ? '<img class="'+cls+'" src="'+p.img+'">' : '<div class="at-thumb-fallback"><i class="fa-solid fa-infinity"></i></div>';
  }
  return toyImgTag(a.toy, cls);
}

/* ---------------- TOAST ---------------- */
let toastTimer=null;
function showToast(msg){
  const t = document.getElementById('toast');
  t.innerHTML = '<i class="fa-solid fa-circle-check"></i> '+msg;
  t.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=> t.classList.remove('show'), 2400);
}

/* ---------------- CONFIRM MODAL (substitui window.confirm, bloqueado em iframes) ---------------- */
let pendingConfirmAction = null;
function askConfirm(title, msg, onConfirm){
  document.getElementById('confirmTitle').textContent = title;
  document.getElementById('confirmMsg').textContent = msg;
  pendingConfirmAction = onConfirm;
  document.getElementById('confirmOverlay').classList.add('show');
}
function closeConfirm(){
  document.getElementById('confirmOverlay').classList.remove('show');
  pendingConfirmAction = null;
}
document.getElementById('confirmActionBtn').onclick = function(){
  const action = pendingConfirmAction;
  closeConfirm();
  if(action) action();
};

/* ---------------- LOGIN (usuário + senha) ---------------- */
function togglePassView(inputId, btn){
  const el = document.getElementById(inputId);
  const mostrando = el.type === 'text';
  el.type = mostrando ? 'password' : 'text';
  btn.innerHTML = mostrando ? '<i class="fa-regular fa-eye"></i>' : '<i class="fa-regular fa-eye-slash"></i>';
}
/* Enter no usuário pula para a senha; Enter na senha entra */
function loginKey(ev, campo){
  if(ev.key !== 'Enter') return;
  ev.preventDefault();
  if(campo==='user') document.getElementById('loginPass').focus();
  else doLogin();
}
function renderLoginHint(){
  const el = document.getElementById('loginHint');
  if(!el) return;
  const g = users.find(u=>u.role==='gestor' && u.status==='ativo');
  const m = users.find(u=>u.role==='monitor' && u.status==='ativo');
  el.innerHTML = '<b>Acessos de demonstração</b>' +
    (g ? '<div>Gestor: '+g.email+' · senha '+g.senha+'</div>' : '') +
    (m ? '<div>Monitor: '+m.email+' · senha '+m.senha+'</div>' : '');
}
function doLogin(){
  const login = document.getElementById('loginUser').value.trim().toLowerCase();
  const senha = document.getElementById('loginPass').value;
  if(!login || !senha){ showToast('Informe usuário e senha.'); return; }
  const u = users.find(x=>(x.email||'').toLowerCase() === login);
  if(!u || u.senha !== senha){ showToast('Usuário ou senha incorretos.'); return; }
  if(u.status !== 'ativo'){ showToast('Usuário inativo. Procure um gestor para reativar o acesso.'); return; }
  currentUser = u; currentRole = u.role;
  document.getElementById('loginPass').value = '';
  applyRoleUI();
  go('home');
  showToast('Bem-vindo(a), '+u.name.split(' ')[0]+'.');
}

