/* ---------------- AUTORIZAÇÃO DO GESTOR ----------------
   Usada quando o monitor não pode receber pagamentos (configuração desligada). */
let authSelectedGestor = null;
let pendingAuthAction = null;
function precisaAutorizacaoGestor(){
  return currentRole === 'monitor' && !getSetting('monitorPodeReceberPagamento');
}
function askGestorAuth(onOk){
  const gestores = users.filter(u=>u.role==='gestor' && u.status==='ativo');
  if(gestores.length===0){ showToast('Nenhum gestor ativo para autorizar.'); return; }
  pendingAuthAction = onOk;
  authSelectedGestor = gestores[0].name;
  document.getElementById('authSenha').value = '';
  renderAuthGestores();
  document.getElementById('authOverlay').classList.add('show');
}
function renderAuthGestores(){
  const gestores = users.filter(u=>u.role==='gestor' && u.status==='ativo');
  document.getElementById('authGestorChips').innerHTML = gestores.map(g=>
    '<button type="button" class="chip'+(authSelectedGestor===g.name?' sel':'')+'" onclick="pickAuthGestor(\''+g.name.replace(/'/g,"\\'")+'\')">'+g.name.split(' ')[0]+'</button>').join('');
}
function pickAuthGestor(name){ authSelectedGestor = name; renderAuthGestores(); }
function closeAuth(){
  document.getElementById('authOverlay').classList.remove('show');
  pendingAuthAction = null;
}
function confirmAuth(){
  const g = users.find(u=>u.name===authSelectedGestor);
  const senha = document.getElementById('authSenha').value;
  if(!g){ showToast('Selecione um gestor.'); return; }
  if(!senha || g.senha !== senha){ showToast('Senha do gestor incorreta.'); return; }
  const action = pendingAuthAction;
  closeAuth();
  showToast('Autorizado por '+g.name.split(' ')[0]+'.');
  if(action) action();
}

