/* ---------------- ROLE UI ---------------- */
function applyRoleUI(){
  const isMonitor = currentRole === 'monitor';
  document.getElementById('roleBadge').textContent = isMonitor ? 'Monitor' : 'Gestor';
  document.querySelectorAll('.tab').forEach(t=>{
    const restricted = (t.dataset.t==='locacoes' || t.dataset.t==='relatorios');
    t.classList.toggle('role-hidden', isMonitor && restricted);
  });
  const firstName = currentUser.name.split(' ')[0];
  document.getElementById('homeGreet').textContent = 'Boa tarde, '+firstName;
  document.getElementById('statFaturado').classList.toggle('role-hidden', isMonitor);
  document.getElementById('statCountLbl').textContent = isMonitor ? 'Meus atend. hoje' : 'Atendimentos';
  document.getElementById('statCount').textContent = isMonitor ? '5' : '14';
  renderMenu();
  renderAtLists();
}

/* ---------------- NAV ---------------- */
const screens = ['login','home','novo','ativos','atendimento','pagamento','locacoes','relatorios','cadastroBrinquedos','cadastroPacotes','cadastroUsuarios','configuracoes'];
const noAppbar = ['login'];
const noTabbar = ['login','atendimento','pagamento','cadastroBrinquedos','cadastroPacotes','cadastroUsuarios','configuracoes'];
function go(name){
  if(currentRole==='monitor' && ['locacoes','relatorios','cadastroBrinquedos','cadastroPacotes','cadastroUsuarios','configuracoes'].includes(name)) name='home';
  closeMenu();
  screens.forEach(s=> document.getElementById('screen-'+s).classList.toggle('active', s===name));
  document.getElementById('appbar').classList.toggle('show', !noAppbar.includes(name));
  document.getElementById('roleBadge').style.display = (name==='login') ? 'none' : '';
  document.getElementById('tabbar').classList.toggle('hidden', noTabbar.includes(name));
  document.querySelectorAll('.tab').forEach(t=> t.classList.toggle('active', t.dataset.t===name));
  document.getElementById('fabLoc').classList.toggle('show', name==='locacoes');
  if(name==='locacoes') document.getElementById('locForm').style.display='none';
  if(name==='pagamento'){ document.getElementById('payBody').style.display='block'; document.getElementById('successState').classList.remove('show'); }
  if(name==='relatorios') renderReport();
  if(name==='cadastroBrinquedos') renderToys();
  if(name==='cadastroPacotes') renderPacotes();
  if(name==='cadastroUsuarios') renderUsers();
  if(name==='locacoes') renderLocs();
  if(name==='login') renderLoginHint();
  if(name==='configuracoes') renderSettings();
  if(name==='home' || name==='ativos') renderAtLists();
  if(name==='novo') renderToyGridNovo();
}

/* ---------------- ATENDIMENTOS (dynamic) ---------------- */
function urgencyColor(remaining){
  if(remaining<=0) return 'var(--danger)';
  if(remaining<=1) return 'var(--warn)';
  return 'var(--success)';
}
function statusTagHTML(a){
  if(a.paused) return '<span class="tag-paused"><i class="fa-solid fa-pause"></i> Pausado</span>';
  if(a.isPacote) return '';
  const remaining = getRemainingMin(a);
  if(remaining<=0) return '<span class="tag-finished">Tempo finalizado</span>';
  if(remaining<=1) return '<span class="tag-almost">Quase Acabando</span>';
  return '';
}
function togglePauseRecord(a){
  if(!a.paused){
    a.elapsedMs = (a.elapsedMs||0) + (Date.now() - (a.lastResumeAt||Date.now()));
    a.paused = true;
  } else {
    a.lastResumeAt = Date.now();
    a.paused = false;
  }
}
function togglePauseFromRow(id){
  const a = atendimentosAtivos.find(x=>x.id===id);
  if(!a) return;
  togglePauseRecord(a);
  showToast(a.paused ? 'Atendimento pausado.' : 'Atendimento retomado.');
  renderAtLists();
}
function finalizeFromRow(id){
  const a = atendimentosAtivos.find(x=>x.id===id);
  if(!a) return;
  current = a;
  goToPaymentFromDetail(false);
}
let highlightAtendimentoId = null;
let highlightTimer = null;
/* Garante que a aba "Atendimentos" esteja na visão Ativos (e não em Histórico) */
function forceAtivosView(){
  repAtivosView = 'ativos';
  document.querySelectorAll('#screen-ativos .chip-row .chip[data-view]').forEach(c=>
    c.classList.toggle('sel', c.dataset.view==='ativos'));
  document.getElementById('ativosListFull').style.display = 'block';
  document.getElementById('historicoBox').style.display = 'none';
  const footAtivos = document.getElementById('ativosFoot');
  if(footAtivos) footAtivos.style.display = 'block';
  document.getElementById('ativosTitle').textContent = 'Atendimentos ativos';
  document.getElementById('ativosSub').textContent = 'Toque em um card para pausar, estender, antecipar ou finalizar.';
}
/* Destaca e rola até o atendimento recém-criado dentro da listagem */
function highlightAtendimento(id){
  highlightAtendimentoId = id;
  clearTimeout(highlightTimer);
  highlightTimer = setTimeout(()=>{ highlightAtendimentoId = null; renderAtLists(); }, 3000);
  renderAtLists();
  requestAnimationFrame(()=>{
    const row = document.querySelector('#ativosListFull .at-row[data-id="'+id+'"]');
    if(row && row.scrollIntoView) row.scrollIntoView({behavior:'smooth', block:'center'});
  });
}
function renderAtRowHTML(a, withActions){
  const pct = getPct(a);
  const remaining = getRemainingMin(a);
  const remainingStr = String(remaining).padStart(2,'0');
  const clienteTxt = a.cliente ? a.cliente : 'Cliente não identificado';
  const advTag = a.paidAdvance ? '<span class="tag-advance"><i class="fa-solid fa-check"></i> pago</span>' : '';
  const stTag = statusTagHTML(a);
  const color = a.paused ? 'var(--ink-faint)' : urgencyColor(remaining);
  const ringHTML = a.isPacote
    ? '<div class="ring-free"><i class="fa-solid fa-infinity"></i><span>Tempo<br>Livre</span></div>'
    : '<div class="ring" style="--pct:'+pct+'%;--ring-color:'+color+'"><span>'+remainingStr+'m</span></div>';
  const actionsRow = withActions ? (
    '<div class="at-actions">' +
      '<button class="at-btn" onclick="event.stopPropagation();togglePauseFromRow('+a.id+')"><i class="fa-solid fa-'+(a.paused?'play':'pause')+'"></i> '+(a.paused?'Retomar':'Pausar')+'</button>' +
      '<button class="at-btn primary" onclick="event.stopPropagation();finalizeFromRow('+a.id+')"><i class="fa-solid fa-circle-check"></i> Finalizar</button>' +
    '</div>'
  ) : '';
  const newCls = (a.id===highlightAtendimentoId) ? ' at-new' : '';
  return '<div class="at-row'+newCls+'" data-id="'+a.id+'" data-op="'+a.op+'" onclick="openAtendimentoById('+a.id+')">' +
    '<div class="at-row-top">' +
      atendimentoThumbTag(a,'at-thumb') +
      '<div class="at-info"><div class="toy">'+a.toy+' '+advTag+'</div>' +
      '<div class="meta">'+clienteTxt+' · iniciado às '+a.horaInicio+' · '+(a.pacoteTempoLabel || (a.minutos+' min'))+' · <span class="op-tag">'+a.op+'</span></div>' +
      (stTag ? '<div class="row-tagline">'+stTag+'</div>' : '') +
      '</div>' +
      ringHTML +
    '</div>' +
    actionsRow +
  '</div>';
}
function renderHistRowHTML(a){
  const clienteTxt = a.cliente ? a.cliente : 'Cliente não identificado';
  const valorFinal = (typeof a.valorFinal === 'number') ? a.valorFinal : a.valor;
  const valStr = fmtMoney(valorFinal);
  const descTxt = a.desconto>0 ? '<div style="font-size:9.5px;color:var(--warn);">desconto '+fmtMoney(a.desconto)+'</div>' : '';
  return '<div class="at-row" style="cursor:default;">' +
    '<div class="at-row-top">' +
    '<div class="at-info"><div class="toy">'+a.toy+'</div>' +
    '<div class="meta">'+clienteTxt+' · '+a.minutos+' min utilizados · iniciado às '+a.horaInicio+' · <span class="op-tag">'+a.op.split(' ')[0]+'</span></div></div>' +
    '<div style="text-align:right;flex:0 0 auto;">' +
      '<div style="font-family:\'Sora\',sans-serif;font-weight:800;font-size:13px;color:var(--navy);">'+valStr+'</div>' +
      '<div style="font-size:10px;color:var(--ink-soft);">'+pagamentosLabel(a.pagamentos)+'</div>' + descTxt +
    '</div></div></div>';
}
function setAtivosView(view, el){
  repAtivosView = view;
  document.querySelectorAll('#screen-ativos .chip-row .chip[data-view]').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  const isHist = view==='historico';
  document.getElementById('ativosListFull').style.display = isHist ? 'none':'block';
  document.getElementById('ativosEmptyHint').style.display = 'none';
  document.getElementById('historicoBox').style.display = isHist ? 'block':'none';
  const foot = document.getElementById('ativosFoot');
  if(foot) foot.style.display = isHist ? 'none':'block';
  document.getElementById('ativosTitle').textContent = isHist ? 'Histórico de atendimentos' : 'Atendimentos ativos';
  document.getElementById('ativosSub').textContent = isHist
    ? (currentRole==='monitor' ? 'Seus atendimentos já finalizados.' : 'Todos os atendimentos já finalizados.')
    : 'Toque em um card para pausar, estender, antecipar ou finalizar.';
  renderAtLists();
}
function renderAtLists(){
  // as listagens rolam sozinhas e são redesenhadas a cada segundo: guarda a posição
  const scrollEls = ['homeScroll','ativosScroll'].map(id=>document.getElementById(id)).filter(Boolean);
  const scrollPos = scrollEls.map(el=>el.scrollTop);
  const isMonitor = currentRole==='monitor';
  let list = atendimentosAtivos.filter(a=>a.status==='ativo');
  if(isMonitor) list = list.filter(a=>a.op===currentUser.name);
  document.getElementById('statAndamento').textContent = list.length;

  // Ordena: mais perto de terminar (ou já zerado) no topo; pacotes (tempo livre) por último
  list = list.slice().sort((a,b)=>{
    const ra = a.isPacote ? Infinity : getRemainingMin(a);
    const rb = b.isPacote ? Infinity : getRemainingMin(b);
    return ra - rb;
  });

  const homeList = list.slice(0,3);
  document.getElementById('homeAtList').innerHTML = homeList.map(a=>renderAtRowHTML(a,false)).join('');
  document.getElementById('homeEmptyHint').style.display = homeList.length===0 ? 'block':'none';

  const fullEl = document.getElementById('ativosListFull');
  if(fullEl){
    fullEl.innerHTML = list.map(a=>renderAtRowHTML(a,true)).join('');
    if(repAtivosView==='ativos') document.getElementById('ativosEmptyHint').style.display = list.length===0 ? 'block':'none';
  }

  if(repAtivosView==='historico') renderHistorico();

  scrollEls.forEach((el,i)=>{ if(el.scrollTop!==scrollPos[i]) el.scrollTop = scrollPos[i]; });
}

/* ---------------- HISTORICO: filtros, agrupamento por dia, PDF ---------------- */
let histPeriod = '7dias';
let histMonitor = 'todos';
function getHistRange(){
  let start, end;
  if(histPeriod==='hoje'){ start = end = TODAY; }
  else if(histPeriod==='7dias'){ end = TODAY; start = new Date(TODAY); start.setDate(start.getDate()-6); }
  else {
    const sv = document.getElementById('histDateStart').value;
    const ev = document.getElementById('histDateEnd').value;
    start = sv ? new Date(sv+'T00:00:00') : TODAY;
    end = ev ? new Date(ev+'T00:00:00') : TODAY;
  }
  return {start, end};
}
function setHistPeriod(p, el){
  histPeriod = p;
  document.querySelectorAll('#histPeriodChips .chip').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  document.getElementById('histDateRange').classList.toggle('show', p==='custom');
  if(p==='custom'){
    const s = new Date(TODAY); s.setDate(s.getDate()-6);
    document.getElementById('histDateStart').value = s.toISOString().slice(0,10);
    document.getElementById('histDateEnd').value = TODAY.toISOString().slice(0,10);
  }
  renderHistorico();
}
function setHistMonitor(m, el){
  histMonitor = m;
  document.querySelectorAll('#histMonitorChips .chip').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  renderHistorico();
}
function buildHistMonitorChips(){
  const el = document.getElementById('histMonitorChips');
  const isMonitor = currentRole==='monitor';
  document.getElementById('histMonitorSection').style.display = isMonitor ? 'none' : 'block';
  if(isMonitor) return;
  const finalizados = atendimentosAtivos.filter(a=>a.status==='finalizado');
  const nomes = [...new Set(finalizados.map(a=>a.op))].sort();
  let html = '<button class="chip'+(histMonitor==='todos'?' sel':'')+'" data-m="todos" onclick="setHistMonitor(\'todos\', this)">Todos</button>';
  nomes.forEach(n=>{
    const sel = histMonitor===n ? ' sel':'';
    html += '<button class="chip'+sel+'" data-m="'+n+'" onclick="setHistMonitor(\''+n.replace(/'/g,"\\'")+'\', this)">'+n.split(' ')[0]+'</button>';
  });
  el.innerHTML = html;
}
const HIST_WD = ['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
function fmtHistDayHeader(dateStr){
  const d = new Date(dateStr+'T00:00:00');
  const dd = String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0');
  const todayStr = TODAY.toISOString().slice(0,10);
  const yestStr = new Date(TODAY.getTime()-86400000).toISOString().slice(0,10);
  if(dateStr===todayStr) return 'Hoje · '+dd;
  if(dateStr===yestStr) return 'Ontem · '+dd;
  return HIST_WD[d.getDay()]+' · '+dd;
}
function renderHistorico(){
  buildHistMonitorChips();
  const isMonitor = currentRole==='monitor';
  const {start,end} = getHistRange();
  const startStr = start.toISOString().slice(0,10);
  const endStr = end.toISOString().slice(0,10);

  let hist = atendimentosAtivos.filter(a=>a.status==='finalizado' && a.data>=startStr && a.data<=endStr);
  if(isMonitor) hist = hist.filter(a=>a.op===currentUser.name);
  else if(histMonitor!=='todos') hist = hist.filter(a=>a.op===histMonitor);

  const histEl = document.getElementById('historicoListFull');
  document.getElementById('historicoEmptyHint').style.display = hist.length===0 ? 'block':'none';
  if(hist.length===0){ histEl.innerHTML=''; return; }

  const multiDay = startStr !== endStr;
  if(!multiDay){
    histEl.innerHTML = hist.map(renderHistRowHTML).join('');
    return;
  }
  const groups = {};
  hist.forEach(a=>{ (groups[a.data] = groups[a.data]||[]).push(a); });
  const dias = Object.keys(groups).sort((a,b)=> b.localeCompare(a));
  histEl.innerHTML = dias.map(d=>{
    const itens = groups[d];
    const total = itens.reduce((s,a)=>s+a.valor,0);
    return '<div class="filter-label" style="margin:14px 0 8px;display:flex;justify-content:space-between;">' +
      '<span>'+fmtHistDayHeader(d)+'</span><span>R$ '+total.toFixed(2).replace('.',',')+'</span></div>' +
      itens.map(renderHistRowHTML).join('');
  }).join('');
}
function generateHistPdf(){
  const {start,end} = getHistRange();
  const fname = 'historico-atendimentos_'+start.toISOString().slice(0,10)+'_a_'+end.toISOString().slice(0,10)+'.pdf';
  showToast(fname+' gerado e pronto para compartilhar.');
}

/* ---------------- NOVO ATENDIMENTO ---------------- */
/* Gestor pode atribuir o atendimento a um monitor; monitor sempre é o responsável por si */
let novoOpSelecionado = null;
function renderNovoMonitorChips(){
  const box = document.getElementById('novoMonitorBox');
  if(!box) return;
  const isGestor = currentRole === 'gestor';
  box.style.display = isGestor ? 'block' : 'none';
  if(!isGestor){ novoOpSelecionado = null; return; }
  const monitores = users.filter(u=>u.role==='monitor' && u.status==='ativo');
  if(!novoOpSelecionado || ![currentUser.name, ...monitores.map(m=>m.name)].includes(novoOpSelecionado)){
    novoOpSelecionado = currentUser.name;   // por padrão, o próprio gestor
  }
  const opcoes = [{name:currentUser.name, label:'Eu ('+currentUser.name.split(' ')[0]+')'},
                  ...monitores.map(m=>({name:m.name, label:m.name}))];
  document.getElementById('novoMonitorChips').innerHTML = opcoes.map(o=>
    '<button type="button" class="chip'+(novoOpSelecionado===o.name?' sel':'')+'" onclick="pickNovoMonitor(\''+o.name.replace(/'/g,"\\'")+'\')">'+o.label+'</button>').join('');
}
function pickNovoMonitor(name){ novoOpSelecionado = name; renderNovoMonitorChips(); }
function renderToyGridNovo(){
  const grid = document.getElementById('toyGridNovo');
  const ativos = toys.filter(t=>t.ativo);
  grid.innerHTML = ativos.map((t,i)=>
    '<button class="toy-chip'+(i===0?' sel':'')+'" data-price="'+t.price.replace(',','.')+'" data-name="'+t.name+'" onclick="pickToy(this)">'+
    '<div class="ic"><img src="'+t.img+'"></div><div class="nm">'+t.name+'</div><div class="pr">R$ '+t.price+'/min</div></button>'
  ).join('');
  novoTempoMode = 'minutos';
  pacoteSelecionadoAtendimento = null;
  document.querySelectorAll('#tempoModeChips .chip').forEach(c=>c.classList.toggle('sel', c.dataset.m==='minutos'));
  document.getElementById('tempoMinutosBox').style.display = 'block';
  document.getElementById('tempoPacoteBox').style.display = 'none';
  document.querySelectorAll('.time-chip').forEach(c=>c.classList.toggle('sel', c.dataset.min==='15'));
  document.getElementById('customTimeField').style.display = 'none';
  document.getElementById('customTimeInput').value = '';
  renderNovoMonitorChips();
  updateEstimate();
}
function pickToy(el){
  document.querySelectorAll('#toyGridNovo .toy-chip').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  updateEstimate();
}
function pickTime(el){
  document.querySelectorAll('.time-chip').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  const isCustom = el.dataset.min==='custom';
  document.getElementById('customTimeField').style.display = isCustom ? 'flex' : 'none';
  if(isCustom) document.getElementById('customTimeInput').focus();
  updateEstimate();
}
function getSelectedMinutos(){
  const time = document.querySelector('.time-chip.sel');
  if(!time) return null;
  if(time.dataset.min==='custom'){
    const v = parseInt(document.getElementById('customTimeInput').value);
    return (v && v>0) ? v : null;
  }
  return parseInt(time.dataset.min);
}
function setTempoMode(mode, el){
  novoTempoMode = mode;
  document.querySelectorAll('#tempoModeChips .chip').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  document.getElementById('tempoMinutosBox').style.display = mode==='minutos' ? 'block':'none';
  document.getElementById('tempoPacoteBox').style.display = mode==='pacote' ? 'block':'none';
  if(mode==='pacote') renderPacoteAtendimentoList();
  updateEstimate();
}
function renderPacoteAtendimentoList(){
  const list = pacotes.map((p,idx)=>({p,idx})).filter(x=>x.p.ativo && x.p.exibePacoteAtendimento);
  const el = document.getElementById('pacoteAtendimentoList');
  document.getElementById('pacoteAtendimentoEmpty').style.display = list.length===0 ? 'block':'none';
  el.innerHTML = list.map(({p,idx})=>{
    const tempoTxt = pacoteTempoTexto(p);
    const sel = pacoteSelecionadoAtendimento===idx ? ' sel' : '';
    return '<button type="button" class="toy-chip'+sel+'" style="width:100%;text-align:left;margin-bottom:10px;flex-direction:row;align-items:center;gap:12px;" data-idx="'+idx+'" onclick="pickPacoteAtendimento('+idx+')">'+
      '<div class="ic"><i class="fa-solid fa-box"></i></div>'+
      '<div style="flex:1;min-width:0;">'+
        '<div class="nm">'+p.name+'</div>'+
        '<div class="pr">R$ '+p.valor+' · '+tempoTxt+'</div>'+
        '<div style="font-size:11px;color:var(--ink-soft);margin-top:2px;"><i class="fa-solid fa-shapes"></i> '+p.toyNames.join(', ')+'</div>'+
      '</div>'+
    '</button>';
  }).join('');
}
function pickPacoteAtendimento(idx){
  pacoteSelecionadoAtendimento = idx;
  document.querySelectorAll('#pacoteAtendimentoList .toy-chip').forEach(c=> c.classList.toggle('sel', parseInt(c.dataset.idx)===idx));
  updateEstimate();
}
function updateEstimate(){
  if(novoTempoMode==='pacote'){
    if(pacoteSelecionadoAtendimento===null){ return; }
    const p = pacotes[pacoteSelecionadoAtendimento];
    const valor = parseFloat((p.valor||'0').replace(',','.'))||0;
    const tempoTxt = pacoteTempoTexto(p);
    document.getElementById('estVal').textContent = 'R$ '+valor.toFixed(2).replace('.',',');
    document.querySelector('#screen-novo .pill').innerHTML = '<i class="fa-regular fa-clock"></i> '+tempoTxt;
    return;
  }
  const toyEl = document.querySelector('#toyGridNovo .toy-chip.sel');
  const min = getSelectedMinutos();
  if(!toyEl || !min) return;
  const price = parseFloat(toyEl.dataset.price);
  const val = (price*min).toFixed(2).replace('.',',');
  document.getElementById('estVal').textContent = 'R$ '+val;
  document.querySelector('#screen-novo .pill').innerHTML = '<i class="fa-regular fa-clock"></i> '+min+' min';
}
function startAtendimento(){
  const clienteInput = document.getElementById('novoClienteInput')
    || document.querySelector('#screen-novo input[placeholder^="Nome da criança"]');
  const cliente = clienteInput ? clienteInput.value.trim() : '';
  const telInput = document.getElementById('novoClienteTelefone');
  const respInput = document.getElementById('novoResponsavel');
  const clienteTelefone = telInput ? telInput.value.trim() : '';
  const responsavel = respInput ? respInput.value.trim() : '';
  const now = new Date();
  const horaInicio = String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');
  const opResponsavel = (currentRole==='gestor' && novoOpSelecionado) ? novoOpSelecionado : currentUser.name;
  let record;
  if(novoTempoMode==='pacote'){
    if(pacoteSelecionadoAtendimento===null){ showToast('Selecione um pacote de tempo fixo.'); return; }
    const p = pacotes[pacoteSelecionadoAtendimento];
    const valor = parseFloat((p.valor||'0').replace(',','.'))||0;
    const minutosNum = pacoteTempoEmMinutos(p);
    record = {id: atendimentoIdSeq++, toy: p.name, cliente: cliente||null, op: opResponsavel,
      horaInicio, minutos: minutosNum, pctElapsed:0, valor, paidAdvance:false, status:'ativo',
      isPacote:true, pacoteTempoLabel: pacoteTempoTexto(p)};
  } else {
    const toyEl = document.querySelector('#toyGridNovo .toy-chip.sel');
    const min = getSelectedMinutos();
    if(!toyEl || !min){ showToast('Escolha o brinquedo e o tempo.'); return; }
    const price = parseFloat(toyEl.dataset.price);
    record = {id: atendimentoIdSeq++, toy: toyEl.dataset.name, cliente: cliente||null, op: opResponsavel,
      horaInicio, minutos: min, pctElapsed:0, valor: price*min, paidAdvance:false, status:'ativo'};
  }
  record.elapsedMs = 0;
  record.lastResumeAt = Date.now();
  record.paused = false;
  record.alertPlayed = false;
  record.data = TODAY.toISOString().slice(0,10);
  record.clienteTelefone = clienteTelefone || null;
  record.responsavel = responsavel || null;
  record.pagamentos = [];
  record.desconto = 0;
  atendimentosAtivos.unshift(record);
  if(clienteInput) clienteInput.value = '';
  if(telInput) telInput.value = '';
  if(respInput) respInput.value = '';
  showToast('Atendimento iniciado.');
  forceAtivosView();          // se a aba estava em Histórico, o novo atendimento ficava invisível
  go('ativos');
  highlightAtendimento(record.id);
}
/* ---------------- ATENDIMENTO DETAIL ---------------- */
let current = null;
let payIsAdvance = false;
function updateDetailScreen(a){
  const remaining = getRemainingMin(a);
  const pct = getPct(a);
  document.getElementById('detailToy').textContent = a.toy;
  document.getElementById('detailMeta').innerHTML = (a.cliente||'Sem nome') + ' · iniciado às '+a.horaInicio+' · <span class="op-tag">'+a.op+'</span>';
  const ring = document.getElementById('detailRing');
  ring.classList.toggle('big-ring-free', !!a.isPacote);
  if(a.isPacote){
    document.getElementById('detailTime').innerHTML = '<i class="fa-solid fa-infinity"></i>';
    document.querySelector('#detailRing small').textContent = 'Tempo livre';
  } else {
    document.getElementById('detailTime').textContent = remaining+' min';
    document.querySelector('#detailRing small').textContent = 'restantes';
  }
  ring.style.setProperty('--dpct', pct+'%');
  document.getElementById('detailThumb').src = a.isPacote ? ((getPacote(a.toy)||{}).img || '') : (getToy(a.toy)||{}).img || '';
  const contatoEl = document.getElementById('detailContato');
  if(contatoEl){
    const partes = [];
    if(a.clienteTelefone) partes.push('<i class="fa-solid fa-phone"></i> '+a.clienteTelefone);
    if(a.responsavel) partes.push('<i class="fa-solid fa-user-shield"></i> Resp.: '+a.responsavel);
    contatoEl.innerHTML = partes.join(' · ');
    contatoEl.style.display = partes.length ? 'block' : 'none';
  }
  document.getElementById('detailTimeTag').innerHTML = statusTagHTML(a);
}
function openAtendimentoById(id){
  current = atendimentosAtivos.find(a=>a.id===id);
  if(!current) return;
  updateDetailScreen(current);
  document.getElementById('pauseBtn').innerHTML = current.paused
    ? '<i class="fa-solid fa-play"></i> Retomar' : '<i class="fa-solid fa-pause"></i> Pausar';
  document.getElementById('pauseBtn').classList.toggle('on', !!current.paused);
  document.getElementById('detailStatus').textContent = current.paused ? 'Pausado' : 'Em andamento';
  document.getElementById('detailStatus').className = 'status-chip ' + (current.paused ? 'pausado' : 'andamento');
  document.getElementById('extendRow').classList.remove('show');
  document.getElementById('trocaBox').style.display = 'none';
  document.getElementById('trocaBtn').style.display = current.isPacote ? 'none' : 'flex';
  updateAdvanceUI();
  go('atendimento');
}
function updateAdvanceUI(){
  const badge = document.getElementById('advanceBadge');
  const advBtn = document.getElementById('advanceBtn');
  const restanteBox = document.getElementById('detailRestante');
  const parcial = isPagoParcial(current);
  badge.style.display = current.paidAdvance ? 'inline-block' : 'none';
  badge.className = 'status-chip ' + (parcial ? 'parcial' : 'advance');
  badge.innerHTML = parcial
    ? '<i class="fa-solid fa-circle-half-stroke"></i> Pago Parcial'
    : '<i class="fa-solid fa-check"></i> Pago antecipado';
  advBtn.style.display = current.paidAdvance ? 'none' : 'flex';
  if(restanteBox){
    restanteBox.style.display = parcial ? 'flex' : 'none';
    document.getElementById('detailRestanteVal').textContent = fmtMoney(valorRestante(current));
  }
}
function togglePause(){
  const btn = document.getElementById('pauseBtn');
  const status = document.getElementById('detailStatus');
  togglePauseRecord(current);
  if(current.paused){
    btn.innerHTML = '<i class="fa-solid fa-play"></i> Retomar'; btn.classList.add('on');
    status.textContent = 'Pausado'; status.className = 'status-chip pausado';
    showToast('Atendimento pausado.');
  } else {
    btn.innerHTML = '<i class="fa-solid fa-pause"></i> Pausar'; btn.classList.remove('on');
    status.textContent = 'Em andamento'; status.className = 'status-chip andamento';
    showToast('Atendimento retomado.');
  }
  updateDetailScreen(current);
}
function toggleExtend(){ document.getElementById('extendRow').classList.toggle('show'); }
let extendLock = false;
/* Valor já quitado do atendimento (pagamento antecipado) */
function valorPago(a){ return a.valorPagoAntecipado || 0; }
/* Quanto ainda falta cobrar: total recalculado menos o que já foi pago */
function valorRestante(a){ return Math.max(0, +((a.valor || 0) - valorPago(a)).toFixed(2)); }
function isPagoParcial(a){ return !!a.paidAdvance && valorRestante(a) > 0; }

function extendTime(min){
  if(extendLock) return;
  extendLock = true;
  current.minutos += min;
  current.alertPlayed = false;
  // Atendimento por tempo já pago: recalcula o valor total pelo novo tempo (pacote/Tempo Livre não tem preço/min)
  if(!current.isPacote){
    const t = getToy(current.toy);
    if(t) current.valor = +(parseMoney(t.price) * current.minutos).toFixed(2);
  }
  updateAdvanceUI();
  updateDetailScreen(current);
  document.getElementById('extendRow').classList.remove('show');
  showToast('Tempo estendido em +'+min+' min.');
  setTimeout(()=>{ extendLock = false; }, 400);
}

/* ---------------- TROCA DE BRINQUEDO ---------------- */
let trocaSelectedToy = null;
function toggleTroca(){
  const box = document.getElementById('trocaBox');
  const willShow = box.style.display==='none' || !box.style.display;
  if(willShow) renderTrocaToyGrid();
  box.style.display = willShow ? 'block' : 'none';
}
function renderTrocaToyGrid(){
  trocaSelectedToy = null;
  const grid = document.getElementById('trocaToyGrid');
  const ativos = toys.filter(t=>t.ativo && t.name!==current.toy);
  grid.innerHTML = ativos.map(t=>
    '<button type="button" class="toy-chip" data-name="'+t.name+'" data-price="'+t.price.replace(',','.')+'" onclick="pickTrocaToy(this)">'+
    '<div class="ic"><img src="'+t.img+'"></div><div class="nm">'+t.name+'</div><div class="pr">R$ '+t.price+'/min</div></button>'
  ).join('');
  document.getElementById('trocaRecalcFlag').checked = true;
}
function pickTrocaToy(el){
  document.querySelectorAll('#trocaToyGrid .toy-chip').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  trocaSelectedToy = {name: el.dataset.name, price: parseFloat(el.dataset.price)};
}
function confirmTrocaBrinquedo(){
  if(!trocaSelectedToy){ showToast('Escolha o novo brinquedo.'); return; }
  const recalc = document.getElementById('trocaRecalcFlag').checked;
  const novoNome = trocaSelectedToy.name;
  current.toy = novoNome;
  if(recalc){
    current.valor = +(trocaSelectedToy.price * current.minutos).toFixed(2);
  }
  document.getElementById('trocaBox').style.display='none';
  updateDetailScreen(current);
  renderAtLists();
  showToast('Brinquedo trocado para '+novoNome+(recalc ? ' — valor recalculado.' : ' — valor mantido.'));
}
function goToPaymentFromDetail(isAdvance){
  const restante = valorRestante(current);
  if(!isAdvance && current.paidAdvance && restante <= 0){
    showToast('Atendimento encerrado — pagamento já recebido antecipadamente.');
    current.pctElapsed = getPct(current);
    current.status = 'finalizado';
    renderAtLists();
    go('ativos');
    return;
  }
  payIsAdvance = isAdvance;
  document.getElementById('pagTitle').textContent = isAdvance ? 'Antecipar pagamento' : 'Finalizar';
  // se já houve pagamento antecipado, cobra apenas o que falta
  const aCobrar = current.paidAdvance ? restante : current.valor;
  openPayment(current.toy, (current.cliente||'Sem nome')+' · '+current.minutos+' min', current.op, aCobrar);
}

/* ---------------- PAGAMENTO ----------------
   Serve atendimentos e locações. Desconto, 4 meios da modelagem
   (PIX / DINHEIRO / CREDITO / DEBITO) e pagamento dividido em parcelas
   que só entram na lista após confirmação explícita. */
let payValor = 18;          // valor cheio, antes do desconto
let payDesconto = 0;
let payLines = [];          // parcelas confirmadas: [{metodo, valor}]
let payMethod = null;       // método em edição
let payTarget = null;       // {tipo:'atendimento'|'locacao', locIndex}

function payTotal(){ return Math.max(0, +(payValor - payDesconto).toFixed(2)); }
function payPago(){ return +somaPagamentos(payLines).toFixed(2); }
function payRestante(){ return Math.max(0, +(payTotal() - payPago()).toFixed(2)); }

function resetPayState(valor){
  payValor = valor || 0;
  payDesconto = 0;
  payLines = [];
  payMethod = null;
  document.getElementById('payDesconto').value = '0,00';
  document.getElementById('cashInput').value = '';
  document.getElementById('payLineValor').value = '';
  document.querySelectorAll('.pm').forEach(c=>c.classList.remove('sel'));
  document.querySelectorAll('.pay-panel').forEach(p=>p.classList.remove('show'));
}

/* Abre a cobrança de um atendimento */
function openPayment(toy, meta, op, valor){
  payTarget = {tipo:'atendimento'};
  resetPayState(valor || 0);
  document.getElementById('payRing').style.display = '';
  document.getElementById('payToy').textContent = toy;
  document.getElementById('payMeta').textContent = meta + (op ? ' · atendido por '+op.split(' ')[0] : '');
  refreshPayUI();
  go('pagamento');
}

/* Abre a cobrança de uma locação (o pagamento total muda o status para Finalizado) */
function openLocPayment(i){
  const l = locacoes[i];
  payTarget = {tipo:'locacao', locIndex:i};
  const restante = Math.max(0, locValorTotal(l) - locValorPago(l) - (l.desconto||0));
  resetPayState(restante);
  document.getElementById('pagTitle').textContent = 'Pagamento da locação';
  document.getElementById('payRing').style.display = 'none';
  document.getElementById('payToy').textContent = l.evento || l.cliente;
  const pago = locValorPago(l);
  document.getElementById('payMeta').textContent = l.cliente + ' · ' + fmtDateBR(l.data) +
    (pago>0 ? ' · já pago '+fmtMoney(pago)+' de '+fmtMoney(locValorTotal(l)) : '');
  refreshPayUI();
  go('pagamento');
}

function applyDesconto(){
  const d = parseMoney(document.getElementById('payDesconto').value);
  payDesconto = Math.min(Math.max(0,d), payValor);
  refreshPayUI();
}

function buildCashChips(){
  const alvo = Math.max(payLineValorAtual() || payRestante(), 0.01);
  const notes = [alvo, Math.ceil(alvo/10)*10, Math.ceil(alvo/50)*50];
  const uniq = [...new Set(notes.map(n=>Math.max(n,alvo)))].slice(0,3);
  document.getElementById('cashChips').innerHTML = uniq.map(v=>'<button class="cash-chip" onclick="setCash('+v+')">'+fmtMoney(v)+'</button>').join('');
}
function setCash(v){ document.getElementById('cashInput').value = v.toFixed(2).replace('.',','); calcTroco(); }
function calcTroco(){
  const recebido = parseMoney(document.getElementById('cashInput').value);
  const troco = recebido - payLineValorAtual();
  const el = document.getElementById('trocoVal');
  el.textContent = fmtMoney(Math.abs(troco));
  el.classList.toggle('neg', troco < 0);
  updateAddLineState();
}

function payLineValorAtual(){
  const v = parseMoney(document.getElementById('payLineValor').value);
  return v > 0 ? v : 0;
}
function onPayLineValorInput(){
  if(payMethod==='DINHEIRO'){ buildCashChips(); calcTroco(); }
  else updateAddLineState();
}

/* Toca em um método: abre a entrada do valor daquela parcela */
function pickPay(el, metodo){
  payMethod = metodo;
  document.querySelectorAll('.pm').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  document.querySelectorAll('.pay-panel').forEach(p=>p.classList.remove('show'));
  if(metodo==='PIX') document.getElementById('panelPix').classList.add('show');
  if(metodo==='DINHEIRO'){ document.getElementById('panelDinheiro').classList.add('show'); document.getElementById('cashInput').value=''; }
  if(metodo==='CREDITO' || metodo==='DEBITO') document.getElementById('panelCartao').classList.add('show');
  document.getElementById('payLineBox').style.display = 'block';
  document.getElementById('payLineValor').value = payRestante() > 0 ? payRestante().toFixed(2).replace('.',',') : '';
  document.getElementById('qrValor').textContent = fmtMoney(payLineValorAtual());
  buildCashChips();
  if(metodo==='DINHEIRO') calcTroco(); else updateAddLineState();
}

/* Confirma a parcela e joga na lista de pagamentos registrados */
function addPayLine(){
  if(!payMethod){ showToast('Escolha a forma de pagamento.'); return; }
  const valor = Math.min(payLineValorAtual(), payRestante());
  if(valor <= 0){ showToast('Informe o valor da parcela.'); return; }
  if(payMethod==='DINHEIRO' && parseMoney(document.getElementById('cashInput').value) < valor){
    showToast('Valor recebido em dinheiro é menor que a parcela.'); return;
  }
  if(payMethod==='DINHEIRO'){
    const troco = parseMoney(document.getElementById('cashInput').value) - valor;
    if(troco > 0) payTrocoPendente = troco;
  }
  payLines.push({metodo:payMethod, valor});
  showToast(PAY_LABELS[payMethod]+': '+fmtMoney(valor)+' adicionado.');
  payMethod = null;
  document.getElementById('cashInput').value = '';
  document.getElementById('payLineValor').value = '';
  document.querySelectorAll('.pm').forEach(c=>c.classList.remove('sel'));
  document.querySelectorAll('.pay-panel').forEach(p=>p.classList.remove('show'));
  document.getElementById('payLineBox').style.display = 'none';
  refreshPayUI();
}
let payTrocoPendente = 0;
function removePayLine(i){
  payLines.splice(i,1);
  refreshPayUI();
}

function renderPayLines(){
  const box = document.getElementById('payLinesBox');
  const list = document.getElementById('payLinesList');
  box.style.display = payLines.length ? 'block' : 'none';
  list.innerHTML = payLines.map((pg,i)=>
    '<div class="pay-line">'+
      '<i class="fa-solid fa-'+(pg.metodo==='DINHEIRO'?'money-bill-wave':(pg.metodo==='PIX'?'qrcode':'credit-card'))+'"></i>'+
      '<span class="nm">'+PAY_LABELS[pg.metodo]+'</span>'+
      '<b>'+fmtMoney(pg.valor)+'</b>'+
      '<button class="pay-line-del" onclick="removePayLine('+i+')"><i class="fa-solid fa-xmark"></i></button>'+
    '</div>').join('');
}

function updateAddLineState(){
  const btn = document.getElementById('addPayLineBtn');
  const valor = payLineValorAtual();
  let ok = !!payMethod && valor > 0;
  if(ok && payMethod==='DINHEIRO' && parseMoney(document.getElementById('cashInput').value) < Math.min(valor, payRestante())) ok = false;
  btn.disabled = !ok;
  document.getElementById('qrValor').textContent = fmtMoney(valor);
}

function refreshPayUI(){
  document.getElementById('payAmount').textContent = fmtMoney(payTotal());
  renderPayLines();
  const restante = payRestante();
  document.getElementById('payPagoVal').textContent = fmtMoney(payPago());        // sempre visível
  document.getElementById('payBalance').style.display = restante > 0 ? 'flex' : 'none';  // some ao zerar
  document.getElementById('payBalanceVal').textContent = fmtMoney(restante);
  document.getElementById('payPickerBox').style.display = restante > 0 ? 'block' : 'none';
  if(restante <= 0){
    payMethod = null;
    document.getElementById('payLineBox').style.display = 'none';
    document.querySelectorAll('.pm').forEach(c=>c.classList.remove('sel'));
    document.querySelectorAll('.pay-panel').forEach(p=>p.classList.remove('show'));
  }
  updateAddLineState();
  updateConfirmState();
}

function updateConfirmState(){
  const btn = document.getElementById('confirmPayBtn');
  const restante = payRestante();
  const isLoc = payTarget && payTarget.tipo==='locacao';
  const parcial = isLoc && restante > 0 && payPago() > 0;
  btn.disabled = !(restante <= 0 || parcial);
  btn.textContent = parcial ? 'Registrar pagamento parcial' : 'Confirmar pagamento';
}

function cancelPayment(){
  if(payTarget && payTarget.tipo==='locacao'){ go('locacoes'); return; }
  go('ativos');
}

/* Confirmação final — passa pela autorização do gestor quando a configuração exigir */
function confirmPayment(){
  if(payPago() <= 0){ showToast('Adicione ao menos uma forma de pagamento.'); return; }
  if(precisaAutorizacaoGestor()){ askGestorAuth(finalizePayment); return; }
  finalizePayment();
}

function finalizePayment(){
  const pagos = [...payLines];
  const totalPago = somaPagamentos(pagos);
  const extra = payTrocoPendente > 0 ? ' Troco de '+fmtMoney(payTrocoPendente)+' entregue ao cliente.' : '';
  const descTxt = payDesconto>0 ? ' Desconto de '+fmtMoney(payDesconto)+' aplicado.' : '';
  payTrocoPendente = 0;

  if(payTarget && payTarget.tipo==='locacao'){
    const l = locacoes[payTarget.locIndex];
    l.pagamentos = [...(l.pagamentos||[]), ...pagos];
    l.desconto = (l.desconto||0) + payDesconto;
    const restanteLoc = locValorTotal(l) - locValorPago(l) - (l.desconto||0);
    const quitada = restanteLoc <= 0.009;
    if(quitada && l.status!=='Cancelada') l.status = 'Finalizado';
    document.getElementById('successTitle').textContent = quitada ? 'Locação quitada' : 'Pagamento registrado';
    document.getElementById('successMsg').innerHTML = fmtMoney(totalPago)+' recebidos via '+pagamentosLabel(pagos)+'.'+extra+descTxt+'<br>'+
      (quitada ? 'Locação marcada como Finalizada.' : 'Restam '+fmtMoney(Math.max(0,restanteLoc))+' para quitar a locação.');
    showSuccessThen(()=>{ renderLocs(); go('locacoes'); });
    return;
  }

  document.getElementById('successTitle').textContent = payIsAdvance ? 'Pagamento antecipado confirmado' : 'Pagamento confirmado';
  document.getElementById('successMsg').innerHTML = fmtMoney(totalPago)+' recebidos via '+pagamentosLabel(pagos)+'.'+extra+descTxt+'<br>'+
    (payIsAdvance ? 'Atendimento continua em andamento.' : 'Atendimento registrado no histórico do dia.');
  showSuccessThen(()=>{
    if(current){
      current.pagamentos = [...(current.pagamentos||[]), ...pagos];
      current.desconto = (current.desconto||0) + payDesconto;
      current.valorPagoAntecipado = +((current.valorPagoAntecipado||0) + totalPago).toFixed(2);
      current.valorFinal = +((current.valorFinal||0) + payTotal()).toFixed(2);
      if(payIsAdvance){ current.paidAdvance = true; updateAdvanceUI(); updateDetailScreen(current); go('atendimento'); }
      else { current.pctElapsed = getPct(current); current.status = 'finalizado'; renderAtLists(); go('home'); }
    } else { go('home'); }
  });
}

function showSuccessThen(fn){
  document.getElementById('payBody').style.display='none';
  document.getElementById('successState').classList.add('show');
  setTimeout(fn, 1900);
}

/* ---------------- FECHAMENTO DE CAIXA ---------------- */
const MONITORS = ['Edmara Braz','Carlos Silva','Ana Paula'];
const TODAY = new Date('2026-08-17T00:00:00');
let salesData = [];
(function buildData(){
  for(let i=12;i>=0;i--){
    const d = new Date(TODAY); d.setDate(d.getDate()-i);
    MONITORS.forEach(m=>{
      const atendimentos = 3 + Math.floor(Math.random()*7);
      const ticket = 14 + Math.random()*14;
      salesData.push({ date: d.toISOString().slice(0,10), monitor: m, atendimentos, valor: Math.round(atendimentos*ticket) });
    });
  }
})();
let repPeriod = '7dias', repMonitor = 'todos';
function setPeriod(p, el){
  repPeriod = p;
  document.querySelectorAll('#periodChips .chip').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  document.getElementById('dateRange').classList.toggle('show', p==='custom');
  if(p==='custom'){
    const s = new Date(TODAY); s.setDate(s.getDate()-6);
    document.getElementById('dateStart').value = s.toISOString().slice(0,10);
    document.getElementById('dateEnd').value = TODAY.toISOString().slice(0,10);
  }
  renderReport();
}
function setMonitorFilter(m, el){
  repMonitor = m;
  document.querySelectorAll('#monitorChips .chip').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  renderReport();
}
function getRange(){
  let start, end;
  if(repPeriod==='hoje'){ start=end=TODAY; }
  else if(repPeriod==='7dias'){ end=TODAY; start=new Date(TODAY); start.setDate(start.getDate()-6); }
  else if(repPeriod==='tudo'){ end=TODAY; start=new Date(TODAY); start.setDate(start.getDate()-12); }
  else {
    const sv=document.getElementById('dateStart').value, ev=document.getElementById('dateEnd').value;
    start = sv? new Date(sv+'T00:00:00') : TODAY;
    end = ev? new Date(ev+'T00:00:00') : TODAY;
  }
  return {start,end};
}
function fmtBRL(n){ return 'R$ '+n.toLocaleString('pt-BR',{maximumFractionDigits:0}); }
function renderReport(){
  const {start,end} = getRange();
  const startStr = start.toISOString().slice(0,10), endStr = end.toISOString().slice(0,10);
  const filtered = salesData.filter(r=> r.date>=startStr && r.date<=endStr && (repMonitor==='todos' || r.monitor===repMonitor));
  const totalValor = filtered.reduce((a,r)=>a+r.valor,0);
  const totalAt = filtered.reduce((a,r)=>a+r.atendimentos,0);
  const ticket = totalAt ? Math.round(totalValor/totalAt) : 0;
  document.getElementById('repTotal').textContent = fmtBRL(totalValor);
  document.getElementById('repCount').textContent = totalAt;
  document.getElementById('repTicket').textContent = fmtBRL(ticket);

  const byDay = {};
  filtered.forEach(r=>{ byDay[r.date]=(byDay[r.date]||0)+r.valor; });
  const days = Object.keys(byDay).sort();
  const maxVal = Math.max(1, ...days.map(d=>byDay[d]));
  const barsEl = document.getElementById('barsChart');
  barsEl.innerHTML='';
  if(days.length===0){ barsEl.innerHTML = '<div class="empty-hint" style="flex:1;">Sem dados no período selecionado.</div>'; }
  days.forEach(d=>{
    const pct = Math.max(6, Math.round((byDay[d]/maxVal)*100));
    const day = d.slice(8,10);
    const col = document.createElement('div');
    col.className='barcol';
    col.innerHTML = '<div class="bar" style="height:'+pct+'%"></div><div class="barlbl">'+day+'</div>';
    barsEl.appendChild(col);
  });

  const byMon = {};
  filtered.forEach(r=>{ if(!byMon[r.monitor]) byMon[r.monitor]={valor:0,atendimentos:0}; byMon[r.monitor].valor+=r.valor; byMon[r.monitor].atendimentos+=r.atendimentos; });
  const monList = Object.keys(byMon).sort((a,b)=>byMon[b].valor-byMon[a].valor);
  const maxMon = Math.max(1, ...monList.map(m=>byMon[m].valor));
  const tableEl = document.getElementById('monitorTable');
  if(monList.length===0){ tableEl.innerHTML = '<div class="empty-hint">Sem dados no período selecionado.</div>'; }
  else {
    tableEl.innerHTML = monList.map(m=>{
      const initials = m.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase();
      const pct = Math.round((byMon[m].valor/maxMon)*100);
      return '<div class="mon-row"><div class="mon-avatar">'+initials+'</div>'+
        '<div class="mon-info"><div class="nm">'+m+'</div><div class="track"><i style="width:'+pct+'%"></i></div></div>'+
        '<div class="mon-val"><b>'+fmtBRL(byMon[m].valor)+'</b><small>'+byMon[m].atendimentos+' atend.</small></div></div>';
    }).join('');
  }
}
function generatePdf(){
  const {start,end} = getRange();
  const fname = 'fechamento-caixa_'+start.toISOString().slice(0,10)+'_a_'+end.toISOString().slice(0,10)+'.pdf';
  showToast(fname+' gerado e pronto para compartilhar.');
}

/* ---------------- CADASTRO DE BRINQUEDOS (com edição e imagem) ---------------- */
let editingToyIndex = null;
let pendingToyImg = null;
/* Cor predominante (tarefa 7): chips comuns + opção de digitar outra */
const TOY_CORES = ['Azul','Vermelho','Amarelo','Verde','Rosa','Laranja','Roxo','Colorido'];
let toyCorSel = null;
function buildToyCorChips(){
  const el = document.getElementById('toyCorChips');
  if(!el) return;
  const outraAtiva = toyCorSel === 'outra';
  el.innerHTML = TOY_CORES.map(c=>
    '<button type="button" class="chip'+(toyCorSel===c?' sel':'')+'" onclick="pickToyCor(\''+c+'\')">'+c+'</button>').join('') +
    '<button type="button" class="chip'+(outraAtiva?' sel':'')+'" onclick="pickToyCor(\'outra\')"><i class="fa-solid fa-palette"></i> Outra</button>';
  document.getElementById('toyCorOutraField').style.display = outraAtiva ? 'flex' : 'none';
}
function pickToyCor(c){
  toyCorSel = (toyCorSel===c) ? null : c;
  buildToyCorChips();
}
function setToyCorFromValue(cor){
  if(!cor){ toyCorSel = null; document.getElementById('newToyCorOutra').value=''; }
  else if(TOY_CORES.includes(cor)){ toyCorSel = cor; document.getElementById('newToyCorOutra').value=''; }
  else { toyCorSel = 'outra'; document.getElementById('newToyCorOutra').value = cor; }
  buildToyCorChips();
}
function getToyCorValue(){
  if(toyCorSel==='outra') return document.getElementById('newToyCorOutra').value.trim() || null;
  return toyCorSel || null;
}
function renderToys(){
  const el = document.getElementById('toysList');
  el.innerHTML = toys.map((t,i)=> '<div class="reg-row" onclick="editToy('+i+')">' +
    '<div class="reg-ic"><img src="'+t.img+'"></div>'+
    '<div class="reg-info"><div class="nm">'+t.name+'</div><div class="meta">R$ '+t.price+'/min · locação R$ '+t.loc+(t.cor?' · '+t.cor:'')+'</div></div>'+
    '<i class="fa-solid fa-pen edit-hint"></i>'+
    '<label class="toggle" onclick="event.stopPropagation()"><input type="checkbox" '+(t.ativo?'checked':'')+' onchange="toggleToy('+i+')"><span class="slider"></span></label></div>').join('');
}
function toggleToy(i){ toys[i].ativo = !toys[i].ativo; showToast(toys[i].name + (toys[i].ativo? ' ativado.':' desativado.')); }
function openToyForm(){
  editingToyIndex = null; pendingToyImg = null;
  document.getElementById('toyFormTitle').textContent = 'Novo brinquedo';
  document.getElementById('newToyName').value='';
  document.getElementById('newToyAge').value='';
  document.getElementById('newToyCap').value='';
  document.getElementById('newToyPrice').value='';
  document.getElementById('newToyLoc').value='';
  document.getElementById('toyImgPreview').style.display='none';
  document.getElementById('toyImgLabel').textContent='Adicionar foto do brinquedo';
  setToyCorFromValue(null);
  document.getElementById('toyForm').style.display='block';
}
function editToy(i){
  editingToyIndex = i; pendingToyImg = toys[i].img;
  document.getElementById('toyFormTitle').textContent = 'Editar brinquedo';
  document.getElementById('newToyName').value = toys[i].name;
  document.getElementById('newToyAge').value = toys[i].age || '';
  document.getElementById('newToyCap').value = toys[i].cap || '';
  document.getElementById('newToyPrice').value = toys[i].price;
  document.getElementById('newToyLoc').value = toys[i].loc;
  const prev = document.getElementById('toyImgPreview');
  prev.src = toys[i].img; prev.style.display='block';
  document.getElementById('toyImgLabel').textContent='Trocar foto';
  setToyCorFromValue(toys[i].cor);
  document.getElementById('toyForm').style.display='block';
  document.getElementById('toyForm').scrollIntoView({behavior:'smooth'});
}
function closeToyForm(){ document.getElementById('toyForm').style.display='none'; }
function previewToyImage(ev){
  const file = ev.target.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = e=>{
    pendingToyImg = e.target.result;
    const prev = document.getElementById('toyImgPreview');
    prev.src = pendingToyImg; prev.style.display='block';
    document.getElementById('toyImgLabel').textContent='Trocar foto';
  };
  reader.readAsDataURL(file);
}
function saveToy(){
  const name = document.getElementById('newToyName').value.trim();
  const age = document.getElementById('newToyAge').value.trim();
  const cap = document.getElementById('newToyCap').value.trim();
  const price = document.getElementById('newToyPrice').value.trim() || '1,00';
  const loc = document.getElementById('newToyLoc').value.trim() || '100,00';
  if(!name){ showToast('Informe o nome do brinquedo.'); return; }
  const img = pendingToyImg || 'data:image/svg+xml;base64,'+btoa('<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"><rect width="100" height="100" fill="%23EAF0FE"/></svg>');
  const cor = getToyCorValue();
  if(editingToyIndex !== null){
    toys[editingToyIndex] = {...toys[editingToyIndex], name, age, cap, price, loc, cor, img};
    showToast('Brinquedo atualizado com sucesso.');
  } else {
    toys.unshift({name, age, cap, price, loc, cor, ativo:true, img});
    showToast('Brinquedo cadastrado com sucesso.');
  }
  closeToyForm();
  renderToys();
}
function toggleForm(id){
  const f = document.getElementById(id);
  f.style.display = (f.style.display==='none' || !f.style.display) ? 'block' : 'none';
}

/* ---------------- CADASTRO DE PACOTES ---------------- */
let editingPacoteIndex = null;
let pacoteSelectedToys = [];
let pendingPacoteImg = null;
function pacoteTempoEmMinutos(p){
  const mult = {minutos:1, horas:60, dias:1440, meses:43200};
  return Math.round((p.tempoValor||0) * (mult[p.tempoUnidade]||1));
}
function pacoteTempoTexto(p){
  const v = p.tempoValor||0;
  const labels = {
    minutos: v===1?'minuto':'minutos',
    horas: v===1?'hora':'horas',
    dias: v===1?'dia':'dias',
    meses: v===1?'mês':'meses'
  };
  return v+' '+(labels[p.tempoUnidade]||'min');
}
function pacoteIcHTML(p){
  return p.img ? '<img src="'+p.img+'">' : '<i class="fa-solid fa-box"></i>';
}
function renderPacotes(){
  const el = document.getElementById('pacotesList');
  el.innerHTML = pacotes.map((p,i)=> {
    const flagTag = p.exibePacoteAtendimento ? ' <span class="tag-advance"><i class="fa-solid fa-eye"></i> exibe no atendimento</span>' : '';
    return '<div class="reg-row" onclick="editPacote('+i+')">'+
    '<div class="reg-ic">'+pacoteIcHTML(p)+'</div>'+
    '<div class="reg-info"><div class="nm">'+p.name+flagTag+'</div><div class="meta">'+p.toyNames.join(' + ')+' · R$ '+p.valor+' · '+pacoteTempoTexto(p)+'</div></div>'+
    '<i class="fa-solid fa-pen edit-hint"></i>'+
    '<label class="toggle" onclick="event.stopPropagation()"><input type="checkbox" '+(p.ativo?'checked':'')+' onchange="togglePacote('+i+')"><span class="slider"></span></label></div>';
  }).join('');
}
function togglePacote(i){ pacotes[i].ativo = !pacotes[i].ativo; showToast(pacotes[i].name + (pacotes[i].ativo? ' ativado.':' desativado.')); }
function buildPacoteToyChips(){
  const especial = '<button type="button" class="chip'+(pacoteSelectedToys.includes('Todos os brinquedos')?' sel':'')+'" onclick="togglePacoteToy(this,\'Todos os brinquedos\')"><i class="fa-solid fa-infinity"></i> Todos os brinquedos</button>';
  document.getElementById('pacoteToyChips').innerHTML = especial + toys.map(t=>
    '<button type="button" class="chip'+(pacoteSelectedToys.includes(t.name)?' sel':'')+'" onclick="togglePacoteToy(this,\''+t.name.replace(/'/g,"\\'")+'\')">'+t.name+'</button>'
  ).join('');
}
function togglePacoteToy(el, name){
  el.classList.toggle('sel');
  if(pacoteSelectedToys.includes(name)) pacoteSelectedToys = pacoteSelectedToys.filter(n=>n!==name);
  else pacoteSelectedToys.push(name);
}
let pacoteTempoUnidade = 'minutos';
function pickPacoteTempoUnidade(el){
  pacoteTempoUnidade = el.dataset.u;
  document.querySelectorAll('#pacoteTempoUnidadeChips .chip').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
}
function previewPacoteImage(ev){
  const file = ev.target.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = e=>{
    pendingPacoteImg = e.target.result;
    const prev = document.getElementById('pacoteImgPreview');
    prev.src = pendingPacoteImg; prev.style.display='block';
    document.getElementById('pacoteImgLabel').textContent='Trocar imagem';
  };
  reader.readAsDataURL(file);
}
function openPacoteForm(){
  editingPacoteIndex = null; pacoteSelectedToys = []; pendingPacoteImg = null;
  document.getElementById('pacoteFormTitle').textContent = 'Novo pacote';
  document.getElementById('newPacoteName').value='';
  document.getElementById('newPacoteValor').value='';
  document.getElementById('newPacoteTempo').value='';
  document.getElementById('newPacoteAtendFlag').checked = false;
  document.getElementById('pacoteImgPreview').style.display='none';
  document.getElementById('pacoteImgLabel').textContent='Adicionar imagem do pacote';
  document.querySelector('#pacoteTempoUnidadeChips .chip[data-u="minutos"]').click();
  buildPacoteToyChips();
  document.getElementById('pacoteForm').style.display='block';
}
function editPacote(i){
  editingPacoteIndex = i;
  pacoteSelectedToys = [...pacotes[i].toyNames];
  pendingPacoteImg = pacotes[i].img || null;
  document.getElementById('pacoteFormTitle').textContent = 'Editar pacote';
  document.getElementById('newPacoteName').value = pacotes[i].name;
  document.getElementById('newPacoteValor').value = pacotes[i].valor;
  document.getElementById('newPacoteTempo').value = pacotes[i].tempoValor;
  document.getElementById('newPacoteAtendFlag').checked = !!pacotes[i].exibePacoteAtendimento;
  document.querySelector('#pacoteTempoUnidadeChips .chip[data-u="'+(pacotes[i].tempoUnidade||'minutos')+'"]').click();
  const prev = document.getElementById('pacoteImgPreview');
  if(pendingPacoteImg){ prev.src = pendingPacoteImg; prev.style.display='block'; document.getElementById('pacoteImgLabel').textContent='Trocar imagem'; }
  else { prev.style.display='none'; document.getElementById('pacoteImgLabel').textContent='Adicionar imagem do pacote'; }
  buildPacoteToyChips();
  document.getElementById('pacoteForm').style.display='block';
  document.getElementById('pacoteForm').scrollIntoView({behavior:'smooth'});
}
function closePacoteForm(){ document.getElementById('pacoteForm').style.display='none'; }
function savePacote(){
  const name = document.getElementById('newPacoteName').value.trim();
  const valor = document.getElementById('newPacoteValor').value.trim();
  const tempoValor = parseInt(document.getElementById('newPacoteTempo').value) || 0;
  const exibePacoteAtendimento = document.getElementById('newPacoteAtendFlag').checked;
  if(!name){ showToast('Informe o nome do pacote.'); return; }
  if(pacoteSelectedToys.length===0){ showToast('Selecione ao menos um brinquedo.'); return; }
  if(!valor || tempoValor<=0){ showToast('Informe valor e tempo do pacote.'); return; }
  const img = pendingPacoteImg || null;
  if(editingPacoteIndex !== null){
    pacotes[editingPacoteIndex] = {...pacotes[editingPacoteIndex], name, toyNames:[...pacoteSelectedToys], valor, tempoValor, tempoUnidade:pacoteTempoUnidade, exibePacoteAtendimento, img};
    showToast('Pacote atualizado com sucesso.');
  } else {
    pacotes.unshift({name, toyNames:[...pacoteSelectedToys], valor, tempoValor, tempoUnidade:pacoteTempoUnidade, ativo:true, exibePacoteAtendimento, img});
    showToast('Pacote cadastrado com sucesso.');
  }
  closePacoteForm();
  renderPacotes();
}

/* ---------------- CADASTRO DE USUARIOS ---------------- */
let newRole = 'gestor';
function pickNewRole(el){
  newRole = el.dataset.r;
  document.querySelectorAll('#userForm .role-pick .chip').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
}
let editingUserIndex = null;
function renderUsers(){
  const el = document.getElementById('usersList');
  el.innerHTML = users.map((u,i)=> '<div class="reg-row" onclick="editUser('+i+')"><div class="reg-ic"><i class="fa-solid '+(u.role==='gestor'?'fa-key':'fa-user')+'"></i></div>'+
    '<div class="reg-info"><div class="nm">'+u.name+'</div><div class="meta">'+(u.role==='gestor'?'Gestor(a)':'Monitor(a)')+(u.email?' · '+u.email:'')+'</div></div>'+
    '<i class="fa-solid fa-pen edit-hint"></i>'+
    '<label class="toggle" onclick="event.stopPropagation()"><input type="checkbox" '+(u.status==='ativo'?'checked':'')+' onchange="toggleUser('+i+')"><span class="slider"></span></label></div>').join('');
}
function toggleUser(i){
  users[i].status = users[i].status==='ativo' ? 'inativo' : 'ativo';
  showToast(users[i].name + (users[i].status==='ativo' ? ' ativado.':' desativado.'));
  renderLoginHint();
}
function fillUserForm(u){
  document.getElementById('newUserName').value = u ? u.name : '';
  document.getElementById('newUserEmail').value = u ? (u.email||'') : '';
  document.getElementById('newUserTelefone').value = u ? (u.telefone||'') : '';
  document.getElementById('newUserNascimento').value = u ? (u.nascimento||'') : '';
  document.getElementById('newUserSenha').value = u ? (u.senha||'') : '';
  newRole = u ? u.role : 'gestor';
  document.querySelectorAll('#userForm .role-pick .chip').forEach(c=>c.classList.toggle('sel', c.dataset.r===newRole));
}
function openUserForm(){
  editingUserIndex = null;
  document.getElementById('userFormTitle').textContent = 'Novo usuário';
  fillUserForm(null);
  document.getElementById('userForm').style.display = 'block';
}
function editUser(i){
  editingUserIndex = i;
  document.getElementById('userFormTitle').textContent = 'Editar usuário';
  fillUserForm(users[i]);
  document.getElementById('userForm').style.display = 'block';
  document.getElementById('userForm').scrollIntoView({behavior:'smooth'});
}
function closeUserForm(){ document.getElementById('userForm').style.display='none'; }
function saveUser(){
  const name = document.getElementById('newUserName').value.trim();
  const email = document.getElementById('newUserEmail').value.trim();
  const telefone = document.getElementById('newUserTelefone').value.trim();
  const nascimento = document.getElementById('newUserNascimento').value;
  const senha = document.getElementById('newUserSenha').value;
  if(!name){ showToast('Informe o nome do usuário.'); return; }
  if(!email){ showToast('Informe o e-mail — ele é o usuário de acesso.'); return; }
  const emailEmUso = users.some((u,i)=> i!==editingUserIndex && (u.email||'').toLowerCase()===email.toLowerCase());
  if(emailEmUso){ showToast('Já existe um usuário com esse e-mail.'); return; }
  if(!senha){ showToast('Informe a senha de acesso.'); return; }
  const initials = name.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase();
  if(editingUserIndex !== null){
    const anterior = users[editingUserIndex];
    users[editingUserIndex] = {...anterior, name, role:newRole, initials, email, telefone, nascimento, senha};
    if(currentUser === anterior) currentUser = users[editingUserIndex];   // mantém a sessão coerente
    showToast('Usuário atualizado com sucesso.');
  } else {
    users.push({name, role:newRole, initials, status:'ativo', email, telefone, nascimento, senha});
    showToast('Usuário cadastrado com sucesso.');
  }
  closeUserForm();
  renderUsers();
  renderLoginHint();
}

/* ---------------- LOCACOES CRUD ---------------- */
let editingLocIndex = null;
let locSelectedToys = [];
let locPacoteName = null;
let locStatus = 'Em análise';
let locFilter = 'todas';
function statusClass(s){
  if(s==='Confirmada') return 'confirmada';
  if(s==='Cancelada') return 'cancelada';
  if(s==='Finalizado') return 'finalizado';
  return 'analise';
}
function fmtDateBR(iso){ if(!iso) return ''; const [y,m,d]=iso.split('-'); return d+'/'+m+'/'+y; }
function setLocFilter(f, el){
  locFilter = f;
  document.querySelectorAll('.loc-filter').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
  renderLocs();
}
function renderLocs(){
  const el = document.getElementById('locsList');
  let list = locacoes.map((l,i)=>({l,i}));
  if(locFilter==='confirmadas') list = list.filter(x=>x.l.status==='Confirmada');
  else if(locFilter==='analise') list = list.filter(x=>x.l.status==='Em análise');
  document.getElementById('locsEmptyHint').style.display = list.length===0 ? 'block' : 'none';
  el.innerHTML = list.map(({l,i})=>{
    const cls = statusClass(l.status);
    const clickable = l.status!=='Cancelada';
    const total = locValorTotal(l), pago = locValorPago(l);
    const restante = Math.max(0, total - pago - (l.desconto||0));
    const podePagar = l.status!=='Cancelada' && l.status!=='Finalizado';
    const btns = '<div class="loc-card2-actions">' +
      (podePagar ? '<button class="loc-menu-btn" title="Registrar pagamento" onclick="event.stopPropagation();openLocPayment('+i+')"><i class="fa-solid fa-hand-holding-dollar"></i></button>' : '') +
      (clickable ? '<button class="loc-menu-btn" title="Cancelar locação" onclick="event.stopPropagation();cancelLoc('+i+')"><i class="fa-solid fa-ban"></i></button>' : '') +
      '</div>';
    const itens = [];
    if(l.pacoteName) itens.push('<b>Pacote: '+l.pacoteName+'</b>');
    if(l.toyNames && l.toyNames.length) itens.push(l.toyNames.join(', '));
    const pagoLine = pago>0 ? '<div class="loc-card2-row"><i class="fa-solid fa-hand-holding-dollar"></i> Pago '+fmtMoney(pago)+
      (restante>0 ? ' · restam '+fmtMoney(restante) : ' · quitada')+' · '+pagamentosLabel(l.pagamentos)+'</div>' : '';
    return '<div class="loc-card2 '+cls+'"'+(clickable?' onclick="editLoc('+i+')"':'')+'>' +
      '<div class="loc-card2-header"><div class="loc-card2-title">'+(l.evento||l.cliente)+'</div>' +
      '<span class="loc-badge '+cls+'">'+l.status+'</span>' + btns + '</div>' +
      '<div class="loc-card2-row"><i class="fa-regular fa-user"></i> Cliente: '+l.cliente+'</div>' +
      '<div class="loc-card2-row"><i class="fa-regular fa-calendar"></i> '+fmtDateBR(l.data)+'&nbsp;&nbsp;<i class="fa-regular fa-clock"></i> '+l.horario+'</div>' +
      '<div class="loc-card2-toys"><i class="fa-solid fa-shapes"></i><span>'+(itens.join(' + ') || 'Sem itens.')+'</span></div>' +
      pagoLine +
      '<div class="loc-card2-divider"></div>' +
      '<div class="loc-card2-valor"><span>Valor total</span><b>R$ '+l.valor+'</b></div>' +
    '</div>';
  }).join('');
}
function buildLocPacoteChips(){
  const el = document.getElementById('locPacoteChips');
  if(!el) return;
  const ativos = pacotes.filter(p=>p.ativo);
  el.innerHTML = '<button type="button" class="chip'+(locPacoteName===null?' sel':'')+'" onclick="pickLocPacote(null)">Nenhum</button>' +
    ativos.map(p=>'<button type="button" class="chip'+(locPacoteName===p.name?' sel':'')+'" onclick="pickLocPacote(\''+p.name.replace(/'/g,"\\'")+'\')">'+p.name+'</button>').join('');
}
function pickLocPacote(name){
  locPacoteName = (locPacoteName===name) ? null : name;
  buildLocPacoteChips();
  updateLocValorSuggestion();
}
function buildLocToyChips(){
  document.getElementById('locToyChips').innerHTML = toys.map(t=>
    '<button type="button" class="chip'+(locSelectedToys.includes(t.name)?' sel':'')+'" onclick="toggleLocToy(this,\''+t.name.replace(/'/g,"\\'")+'\')">'+t.name+'</button>'
  ).join('');
}
function toggleLocToy(el, name){
  el.classList.toggle('sel');
  if(locSelectedToys.includes(name)) locSelectedToys = locSelectedToys.filter(n=>n!==name);
  else locSelectedToys.push(name);
  updateLocValorSuggestion();
}
function updateLocValorSuggestion(){
  let sum = 0;
  if(locPacoteName){ const p = getPacote(locPacoteName); if(p) sum += parseMoney(p.valor); }
  locSelectedToys.forEach(n=>{ const t=getToy(n); if(t) sum += parseMoney(t.loc); });
  if(sum>0) document.getElementById('locValor').value = sum.toFixed(2).replace('.',',');
}
function pickLocStatus(el){
  locStatus = el.dataset.s;
  document.querySelectorAll('#locStatusChips .chip').forEach(c=>c.classList.remove('sel'));
  el.classList.add('sel');
}
function openLocForm(){
  editingLocIndex = null; locSelectedToys = []; locStatus = 'Em análise'; locPacoteName = null;
  document.getElementById('locFormTitle').textContent = 'Nova locação';
  document.getElementById('locEvento').value='';
  document.getElementById('locCliente').value='';
  document.getElementById('locTelefone').value='';
  document.getElementById('locEmail').value='';
  document.getElementById('locData').value='';
  document.getElementById('locHorario').value='';
  document.getElementById('locValor').value='';
  document.querySelectorAll('#locStatusChips .chip').forEach(c=>c.classList.remove('sel'));
  document.querySelector('#locStatusChips .chip[data-s="Em análise"]').classList.add('sel');
  buildLocPacoteChips();
  buildLocToyChips();
  document.getElementById('locForm').style.display='block';
  document.getElementById('locForm').scrollIntoView({behavior:'smooth'});
}
function editLoc(i){
  editingLocIndex = i;
  const l = locacoes[i];
  locSelectedToys = [...(l.toyNames||[])];
  locStatus = (l.status==='Finalizado') ? 'Confirmada' : l.status;   // "Finalizado" não é selecionável
  locPacoteName = l.pacoteName || null;
  document.getElementById('locFormTitle').textContent = 'Editar locação';
  document.getElementById('locEvento').value = l.evento || '';
  document.getElementById('locCliente').value = l.cliente;
  document.getElementById('locTelefone').value = l.telefone;
  document.getElementById('locEmail').value = l.email || '';
  document.getElementById('locData').value = l.data;
  document.getElementById('locHorario').value = l.horario;
  document.getElementById('locValor').value = l.valor;
  document.querySelectorAll('#locStatusChips .chip').forEach(c=>c.classList.toggle('sel', c.dataset.s===locStatus));
  buildLocPacoteChips();
  buildLocToyChips();
  document.getElementById('locForm').style.display='block';
  document.getElementById('locForm').scrollIntoView({behavior:'smooth'});
}
function closeLocForm(){ document.getElementById('locForm').style.display='none'; }
function saveLoc(){
  const evento = document.getElementById('locEvento').value.trim();
  const cliente = document.getElementById('locCliente').value.trim();
  const telefone = document.getElementById('locTelefone').value.trim();
  const email = document.getElementById('locEmail').value.trim();
  const data = document.getElementById('locData').value;
  const horario = document.getElementById('locHorario').value.trim();
  const valor = document.getElementById('locValor').value.trim();
  if(!cliente){ showToast('Informe o nome do cliente.'); return; }
  if(!locPacoteName && locSelectedToys.length===0){ showToast('Selecione um pacote ou ao menos um brinquedo.'); return; }
  if(!data || !horario){ showToast('Informe data e horário.'); return; }
  const anterior = editingLocIndex !== null ? locacoes[editingLocIndex] : null;
  const record = {evento: evento||cliente, cliente, telefone, email, data, horario,
    pacoteName: locPacoteName, toyNames:[...locSelectedToys], valor: valor||'0,00', status: locStatus,
    pagamentos: anterior ? (anterior.pagamentos||[]) : [], desconto: anterior ? (anterior.desconto||0) : 0};
  // se já estava quitada, o status "Finalizado" é preservado (não é escolha manual)
  if(anterior && anterior.status==='Finalizado' && locValorPago(record) + (record.desconto||0) >= locValorTotal(record)) record.status = 'Finalizado';
  if(editingLocIndex !== null){
    locacoes[editingLocIndex] = record;
    showToast('Locação atualizada com sucesso.');
  } else {
    locacoes.unshift(record);
    showToast('Locação cadastrada com sucesso.');
  }
  closeLocForm();
  renderLocs();
}
function cancelLoc(i){
  const l = locacoes[i];
  askConfirm(
    'Cancelar locação?',
    'A locação de '+l.cliente+' ('+(l.evento||l.cliente)+') será marcada como cancelada. Esta ação não pode ser desfeita.',
    ()=>{
      locacoes[i].status = 'Cancelada';
      renderLocs();
      showToast('Locação cancelada.');
    }
  );
}

